    // Les explications que ni la chaîne ni un message ctl.* ne portent déjà.
    'infobulle.images-sans-description': 'Un lecteur d’écran annoncerait « image » sans rien pouvoir en dire, et tant que la validation PDF/UA est active, ces images bloquent l’export. Une image posée dans un tableau (le bloc des autrices et auteurs, par exemple) ne se décrit pas dans Médias de l’article : son lien ouvre le tableau, et si elle doit être décrite, signalez-le.',
    'infobulle.tableaux-entete': 'Un lecteur d’écran relie chaque cellule à son en-tête. Sans en-tête déclaré, il ne le peut pas ; avec un en-tête fusionné sur plusieurs colonnes, le PDF ne le rattache qu’à la première, et les colonnes suivantes restent sans en-tête. Un tableau qui n’a réellement pas d’en-tête est légitime.',
    'infobulle.tableau-sans-entete': 'Aucun en-tête n’a été reconnu à l’import. Si la première rangée ou la première colonne en est un (souvent mis en valeur par un fond coloré plutôt que par du gras), déclarez-le : un lecteur d’écran pourra alors relier chaque cellule à son en-tête. Si le tableau n’a réellement pas d’en-tête, il n’y a rien à faire.',
    'infobulle.image-sans-legende': 'Une légende dit ce que l’image montre à toutes et à tous, pas seulement aux lecteurs d’écran.',
