    'exportOjs.erreurDocx': 'Die Word-Fassungen der Artikel, die die Online-Ablage verlangt, konnten nicht erzeugt werden. Der Export bricht hier ab: die Ausgabe käme unvollständig dort an. Versuchen Sie es erneut, und melden Sie es, wenn es sich wiederholt.',
