    'ojs.ou.genre': 'OJS → Einstellungen → Workflow → Bestandteile der Einreichung: die genaue Bezeichnung des Bestandteils',
    'ojs.ou.groupe': 'OJS → Einstellungen → Benutzende und Rollen → Rollen: die genaue Bezeichnung der Autorenrolle',
    'ojs.ou.televerseur': 'OJS → Benutzende und Rollen → Benutzende: das Konto, in dessen Namen die Dateien abgelegt werden',
    'ojs.ou.pays': 'Freiwillig: zweibuchstabiger Code (CH, DE, FR…). Leer gelassen, wird kein Land gesendet',
    'ojs.ou.rubriques': 'OJS → Einstellungen → Zeitschrift → Rubriken: das genaue Kürzel und der genaue Titel',
    'ojs.err.ecriture': 'Die Konfiguration des OJS-Exports wurde nicht gespeichert: {0}',
    'ojs.err.config': '{1}: «{0}» ist nicht erfasst. In OJS ablesen ({2}) und in «Pronto-Einstellungen» → «OJS-Export» eintragen.',
    'ojs.err.locale': 'Die Ausgabe ist in der Sprache «{0}» erfasst, die zu keiner der beiden Zeitschriften gehört ({1}): dazu gibt es keine OJS-Konfiguration. Korrigieren Sie die Zeitschrift in «Metadaten der Ausgabe».',
    'ojs.err.date': '«{0}» ist kein vollständiges Publikationsdatum (JJJJ-MM-TT). Die Ausgabe geht publiziert weg: ohne Datum müsste es in OJS Artikel für Artikel nachgetragen werden. Öffnen Sie «Metadaten der Ausgabe» und erfassen Sie das Publikationsdatum.',
    'ojs.err.ausgabe': 'Der Ordner «{0}» ist keine Ausgabe: seine Metadaten fehlen.',
