    'ojs.err.fiche': 'dieser Artikel hat kein Metadaten-Datenblatt. Öffnen Sie «Metadaten der Artikel», füllen Sie es aus und speichern Sie.',
    'ojs.err.type.inconnu': 'der Typ «{0}» führt zu keiner OJS-Rubrik – in «Pronto-Einstellungen» → «OJS-Export» zuweisen.',
