    'ojs.err.titre.aucun': 'kein Titel (title) in irgendeiner Sprache.',
    'ojs.err.titre.langue': 'der Titel fehlt auf {0}, der Sprache des Artikels – in dieser Sprache wird OJS ihn publizieren.',
    'ojs.err.resume.langue': 'das Abstract fehlt auf {0}, der Sprache des Artikels, und diese Rubrik verlangt eines.',
    'ojs.err.auteur.aucun': 'keine Autorin, kein Autor.',
    'ojs.err.doi.incalculable': 'Der DOI jedes Artikels ergibt sich aus dem Publikationsjahr der Ausgabe und ihrer Nummer, und eines von beiden fehlt: es kann kein DOI weggehen, und ein ohne DOI publizierter Artikel hat keinen dauerhaften Identifikator – das lässt sich nachträglich nicht beheben. Öffnen Sie «Metadaten der Ausgabe», erfassen Sie das Publikationsdatum und die Nummer, und starten Sie den Export erneut.',
    'ojs.err.doi.double': 'Zwei Artikel tragen denselben DOI, «{2}»: «{0}» und «{1}». Ein DOI darf nur einen Artikel bezeichnen. Korrigieren Sie das Datenblatt eines der beiden unter «Metadaten der Artikel», und starten Sie den Export erneut.',
    'ojs.err.pagination.perimee': 'Die Paginierung der Ausgabe ist für {0} nicht mehr aktuell. Die gedruckten Seitenzahlen und der an OJS gesendete Seitenbereich würden nicht mehr übereinstimmen. Klicken Sie auf «Paginierung aktualisieren», und starten Sie den Export erneut.',
    'pagination.confirmer': '{0} Artikel, Seiten 1 bis {1}. {2} PDF werden neu kompiliert.',
    'pagination.confirmer.bouton': 'Aktualisieren',
    'pagination.gele': 'Diese Ausgabe ist gesperrt oder archiviert: ihre Seitenzahlen sind die veröffentlichten und werden nicht mehr neu berechnet.',
    'pagination.fait': 'Paginierung aktuell: Seiten 1 bis {0}.',
    'pagination.dejaajour': 'Die Paginierung ist bereits aktuell: Seiten 1 bis {0}. Nichts neu zu kompilieren.',
    'pagination.trous': 'Einige Artikel sind noch nicht kompiliert: {0}. Kompilieren Sie die Ausgabe, und aktualisieren Sie danach die Paginierung.',
    'pagination.echec': 'Die Paginierung konnte nicht aktualisiert werden. Die Einzelheiten stehen im Kompilierungsprotokoll.',
    'ojs.err.galley': 'die Datei «{0}» wurde noch nicht erzeugt. Wählen Sie «Alles neu kompilieren» und starten Sie den Export erneut.',
    'ojs.err.image.introuvable': 'das Bild «{0}» wird im Text aufgerufen, ist aber auf der Festplatte nicht zu finden. Legen Sie es unter «Medien des Artikels» neu ab oder entfernen Sie es aus dem Text, und starten Sie den Export erneut.',
    'ojs.err.galley.docx': 'die Word-Fassung dieses Artikels («{0}») wurde noch nicht erzeugt. Starten Sie «Ausgabe für OJS exportieren» erneut: sie wird dort selbst erzeugt, bevor die Ablage zusammengestellt wird.',
    'ojs.bloquants': 'Diese Punkte müssen vor dem Export behoben werden:',
    'ojs.couverture.alt': 'Umschlagbild',
    'ojs.avert.volume': 'Band fehlt in den Metadaten der Ausgabe.',
    'ojs.avert.numero': 'Nummer fehlt in den Metadaten der Ausgabe.',
    'ojs.avert.annee': 'keine Jahresangabe im Publikationsdatum der Ausgabe.',
    'ojs.avert.couverture': 'Kein Umschlagbild ({0}) im Hauptordner – <covers> weggelassen.',
    'ojs.avert.pays': 'Land der Autorinnen und Autoren nicht erfasst – <country> wird für alle weggelassen. Bei Bedarf in «Pronto-Einstellungen» → «OJS-Export» erfassen.',
    'ojs.avert.pays.forme': 'Land der Autorinnen und Autoren «{0}»: das ist kein zweibuchstabiger Code – <country> weggelassen.',
    'ojs.avert.langue': 'die Sprache des Artikels ({0}) ist nicht die der Zeitschrift ({1}): OJS publiziert nur in der Sprache der Zeitschrift.',
    'ojs.avert.soustitre': 'Untertitel fehlt.',
    'ojs.avert.resume': 'Abstract fehlt.',
    'ojs.avert.motscles': 'Schlagwörter fehlen.',
    'ojs.avert.motscles.marque': '{0} Schlagwort/Schlagwörter {1} nicht übersetzt (Marke «{2}») – sie gingen so nach OJS.',
    'ojs.avert.doi.sans': 'DOI fehlt, was für diese Rubrik normal ist.',
    'ojs.avert.doi.voulu': 'kein DOI, wie es für diesen Artikel auf seiner Karte entschieden wurde.',
    'ojs.avert.doi.inutile': 'dieser Artikel erhält keinen DOI, und sein Datenblatt trägt einen: «{0}». Er geht nicht weg. Ist er bereits unter diesem DOI erschienen, melden Sie es der Redaktion; andernfalls entfernen Sie ihn aus seinem Datenblatt.',
    'ojs.avert.doi.divergent': 'weg geht der DOI «{0}», von Hand auf dem Datenblatt festgelegt, und nicht «{1}», berechnet aus der Position des Artikels in der Ausgabe. Ist der Artikel bereits unter «{0}» erschienen, ist das der richtige Weg – der Identifikator eines publizierten Artikels wird nicht geändert; andernfalls deaktivieren Sie «DOI von Hand festlegen» auf seinem Datenblatt, um zur Berechnung zurückzukehren.',
    'ojs.avert.doi.forme': 'der von Hand festgelegte DOI «{0}» geht nach OJS, hat aber nicht die Form der DOI dieser Zeitschrift – prüfen Sie Zeitschriftenbuchstabe, Jahr und Nummer, oder deaktivieren Sie «DOI von Hand festlegen», um zu «{1}» zurückzukehren, berechnet aus der Position des Artikels.',
    'ojs.avert.email': '{0} Autorin(nen)/Autor(en) ohne E-Mail (leerer Kontakt in OJS).',
