    'ojs.avert.rorSansNom': 'ROR angegeben ohne ausgeschriebene Affiliation: {0} – OJS verlangt einen Namen zum Identifikator, es geht nichts weg. Ergänzen Sie das Feld Affiliation.',
    'ojs.avert.alt': '{0} Bild(er) ohne Alternativtext und ohne Legende, und nicht als dekorativ erklärt: {1} – sie gingen als dekorative Bilder weg. Im Medienformular nachtragen.',
    'ojs.avert.legende': '{0} Abbildung(en) tragen noch die beim Einfügen gesetzte Standardlegende: {1} – sie würde so unter der Abbildung gedruckt.',
    'ojs.avert.licence.reserves': 'Artikel mit vorbehaltenen Rechten: <licenseUrl> wird weggelassen, und OJS wendet die Standardlizenz der Zeitschrift an. Nach dem Import in OJS prüfen.',
    'ojs.avert.licence.figure': 'Lizenz {0} auf der Titelseite angekündigt, aber {1} Abbildung(en) tragen einen fremden Bildnachweis: {2}. Prüfen Sie, ob die Übernahme unter dieser Lizenz erlaubt ist, oder setzen Sie den Artikel auf vorbehaltene Rechte.',
    'ojs.avert.citations.aucune': 'kein Literaturverzeichnis für diesen Artikel – <citations> weggelassen.',
    'ojs.avert.citations.tables': 'Literaturangaben für diese Ausgabe nicht gesendet: {0}',
    'ojs.avert.citations.corps': 'Literaturverzeichnis noch im Text: gesendet werden die Einträge, die sich aus dem Text erraten lassen. Importieren Sie den Artikel neu, um sie auszulagern.',
    'biblio.titre': 'Titel des Literaturverzeichnisses',
