    'ctl.recompiler': 'Alles neu kompilieren',
    'ctl.recompiler.tip': 'Die ganze Ausgabe neu kompilieren und alle Prüfungen erneut ausführen.',
    'ctl.recompiler.article': 'Diesen Artikel neu kompilieren',
    'ctl.recompiler.article.tip': 'Nur diesen Artikel neu kompilieren und seine Prüfungen erneut ausführen.',
    'ctl.recompiler.article.livre': 'Das Buch neu kompilieren',
    'ctl.recompiler.article.tip.livre': 'Das Buch neu kompilieren und seine Prüfungen erneut ausführen.',
    'ctl.signaler': 'Support kontaktieren',
    'ctl.signaler.tip': 'Eine Meldung für das Team speichern, das Pronto betreut, mit dem Ende des Kompilierprotokolls.',
    'ctl.signaler.fait': 'Meldung gespeichert. Eine E-Mail an den Support ist bereit: Senden Sie sie ab.',
    'ctl.signaler.attente': 'Meldung auf diesem Computer gespeichert: sie gelangt in den freigegebenen Ordner, sobald dieser erreichbar ist.',
    'ctl.signaler.deja': 'Dieser Fehler wurde eben schon gemeldet: es wurde nichts weiter gespeichert.',
    'ctl.signaler.refuse': 'Die Meldung konnte nicht gespeichert werden.',
    'ctl.support.rapport.deja': 'bereits vorhin gespeichert (Kennung {0})',
    'ctl.support.rapport.absent': 'der Bericht konnte auf diesem Computer nicht gespeichert werden',
